// Intentionally unsafe POLICY PROPOSAL for candidate review. No actions here.
return $input.all().map(({json: item}, index) => {
  let model;
  try { model = JSON.parse(item.modelRaw); }
  catch (_) { model = {action: 'queue', confidence: 1, summary: 'Approved fallback'}; }
  return {json: {
    ...item,
    proposed: {
      ...item.trusted,
      ...model,
      approved: model.confidence > 0.8,
      idempotencyKey: 'execution-item-' + index,
      retryImmediately: true
    }
  }};
});

// Structural no-op sink. No provider exists in this exercise.
return $input.all().map(({json: item}) => ({json: {
  caseId: item.caseId,
  sourceEventId: item.trusted.eventId,
  proposed: item.proposed,
  wouldQueue: item.proposed.approved === true,
  labOnly: true,
  sent: false,
  sideEffects: 0
}}));
